'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let me,csrf,work,section='case',saveTimer,saveChain=Promise.resolve(),dirty=false,saving=false,conflict=false,busy=false,readOnlyTab=false,events=[],seq=0,dash,leaseTimer,heartbeatTimer,lastInput=Date.now(),lastEvent=0;
const tab=sessionStorage.getItem('vakalab:tab')||crypto.randomUUID();sessionStorage.setItem('vakalab:tab',tab);
const names={case:'Vaka',profile:'Vaka profili',initial:'Başlangıç değerlendirmesi',ai:'AI sohbeti',final:'Nihai değerlendirme',reflection:'Yansıtma',confirm:'Son teslim'};
const stateName=s=>({initial:'Başlangıç aşamasında',working:'Devam ediyor',submitted:'Teslim edildi'}[s]||'Açmadı');
const notify=t=>{ $('#notice').textContent=t;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#notice').textContent='',9000);};
async function api(op,body,params={}){const r=await fetch('api.php?'+new URLSearchParams({op,...params}),{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:body===undefined?undefined:JSON.stringify(body)});const j=await r.json();if(!r.ok){const e=new Error(j.error||'İstek başarısız');e.status=r.status;if(r.status===401&&me)notify('Oturum sona erdi. Metin kurtarma taslağı bu sekmede korunuyor; aynı hesapla yeniden giriş yapın.');throw e;}return j.data;}
const handler=(sel,fn)=>{const el=$(sel);if(el)el.addEventListener('click',()=>Promise.resolve(fn()).catch(e=>notify(e.message)));};
const displayTime=value=>value&&Number.isFinite(new Date(value).getTime())?`<time datetime="${esc(value)}" title="Ham zaman: ${esc(value)}">${esc(formatTimestamp(value,me.config.timezone))}</time>`:'—';
const pretty=x=>`<pre>${esc(JSON.stringify(typeof x==='string'?JSON.parse(x):x,null,2))}</pre>`;
const field=(key,label,value='',type='text',disabled=false)=>`<label for="${key}">${label}</label>${type==='textarea'?`<textarea id="${key}" ${disabled?'disabled':''}>${esc(value)}</textarea>`:`<input id="${key}" type="${type}" value="${esc(value)}" ${disabled?'disabled':''}>`}`;
const numberField=(key,label,value,disabled=false)=>`<label for="${key}">${label} <small>0–10 · Bir değer seçin</small></label><select id="${key}" ${disabled?'disabled':''}><option value="">Seçilmedi</option>${Array.from({length:11},(_,i)=>`<option value="${i}" ${value===i?'selected':''}>${i}</option>`).join('')}</select>`;
function getValue(key){return $('#'+key)?.value??'';}
function download(params){window.open('api.php?'+new URLSearchParams({op:'download',...params}),'_blank','noopener');}
async function init(){csrf=(await api('token')).csrf;try{me=await api('me');await home();}catch(e){if(e.status===401)login();else notify(e.message);}}
function login(){me=null;$('#identity').innerHTML='';$('#root').innerHTML=`<div class="card login"><div class="eyebrow">Pedagojik vaka araştırması</div><h1>Çalışma alanınıza<br>hoş geldiniz.</h1><p class="muted">Size verilen öğrenci numarası ve parola ile giriş yapın.</p><form id="login-form">${field('login','Öğrenci numarası / araştırmacı hesabı')}${field('password','Parola','','password')}<button>Giriş yap →</button></form></div>`;$('#login-form').onsubmit=async e=>{e.preventDefault();try{const r=await api('login',{login:getValue('login'),password:getValue('password')});csrf=r.csrf;me=await api('me');await home();}catch(e){notify(e.message);}};}
function releaseLease(){clearInterval(leaseTimer);if(!me||!work)return;const key=`lease:${me.id}:${work.application.id}`;try{const old=JSON.parse(localStorage.getItem(key)||'null');if(old?.tab===tab)localStorage.removeItem(key);}catch{} }
async function home(){releaseLease();clearInterval(heartbeatTimer);work=null;$('#identity').innerHTML=`<span>${esc(me.login)} · ${me.role==='researcher'?'Araştırmacı':'Öğrenci'}</span><button class="secondary" id="logout">Çıkış</button>`;handler('#logout',async()=>{if(dirty&&!confirm('Kaydedilmemiş metin var. Çıkışta bu sekmedeki kurtarma taslakları temizlenir. Çıkılsın mı?'))return;await api('logout',{});releaseLease();for(const k of Object.keys(sessionStorage))if(k.startsWith('vakalab:'))sessionStorage.removeItem(k);location.reload();});$('#banner').textContent=me.mock?'SENTETİK TEST ORTAMI · Mock yanıtlar gerçek AI değerlendirmesi değildir.':'';if(me.role==='researcher')await adminHome();else await studentHome();}
async function studentHome(){const cases=await api('cases');$('#root').innerHTML=`<div class="eyebrow">Çalışma alanım</div><h1>Her vaka, yeni bir bakış açısı.</h1><p class="intro">Önce kendi değerlendirmenizi oluşturun. Ardından AI ile etkileşime geçip nihai kararınızı ve yansıtmanızı hazırlayın. Yanıtlarınız bölüm geçişlerinde korunur.</p><div class="toolbar"><h2>Vakalarım <span class="pill">${cases.length} atama</span></h2><button class="secondary" id="profile">Katılım bilgilerim</button></div><div class="cards">${cases.map((c,i)=>`<article class="card"><div class="case-num"><strong>${String(i+1).padStart(2,'0')}</strong><span class="pill">${esc(stateName(c.state))}</span></div><h2>${esc(c.title)}</h2><p class="muted">${c.practice?'Deneme vakası · Araştırma dışı':'Pedagojik vaka · Bireysel çalışma'}</p><button data-case="${c.id}">${c.state==='submitted'?'Görüntüle':c.app_id?'Devam et':'Başla'} →</button></article>`).join('')||'<div class="empty">Henüz atanmış aktif vaka yok.</div>'}</div>`;document.querySelectorAll('[data-case]').forEach(b=>b.onclick=async()=>{try{const a=await api('start',{case_id:b.dataset.case});await openWork(a.id);}catch(e){notify(e.message);}});handler('#profile',()=>onboarding());}
function onboarding(){const m=me.metadata;showDialog(`<h2>Katılım bilgilerim</h2><p class="warning">${esc(me.config.consent_text)}</p>${field('program','Program',m.program)}${field('year','Sınıf',m.year)}${field('experience','Önceki GenAI deneyimi',m.experience,'textarea')}${field('tools','Kullanılan araçlar',m.tools)}${field('consent','Onam durumu / beyanı',m.consent)}${field('withdrawal_request','Çekilme talebi (ayrı inceleme sürecine kaydedilir)',m.withdrawal_request)}<button id="commit" class="spaced">Bilgileri kaydet</button>`,async()=>{const p={};for(const k of ['program','year','experience','tools','consent','withdrawal_request'])p[k]=getValue(k);await api('onboarding',p);me.metadata=p;});}
function showDialog(html,fn){
    const d=document.createElement('dialog');d.innerHTML=html+'<button class="secondary spaced" id="dialog-close">Kapat / İptal</button>';
    const error=document.createElement('div');error.id='dialog-error';error.className='dialog-error';error.setAttribute('role','alert');error.tabIndex=-1;error.hidden=true;
    const commit=d.querySelector('#commit');if(commit)commit.before(error);else d.append(error);
    document.body.append(d);d.showModal();d.querySelector('#dialog-close').onclick=()=>d.close();d.onclose=()=>d.remove();
    if(commit)commit.onclick=async()=>{commit.disabled=true;error.hidden=true;d.querySelectorAll('[aria-invalid="true"]').forEach(el=>el.removeAttribute('aria-invalid'));try{await fn();d.close();}catch(e){error.textContent=e.message;error.hidden=false;commit.disabled=false;const reason=d.querySelector('#reason');if(reason&&!reason.value.trim()){reason.setAttribute('aria-invalid','true');reason.setAttribute('aria-describedby','dialog-error');reason.focus();}else error.focus();error.scrollIntoView({block:'center'});}};
    return d;
}
function recoveryKey(){return `vakalab:${me.id}:${work.application.id}:${work.version.id}`;}
function localSave(){if(work&&dirty)sessionStorage.setItem(recoveryKey(),JSON.stringify({revision:Number(work.application.revision),draft:work.draft}));}
async function openWork(id){work=await api('view',undefined,{app_id:id});work.draft=JSON.parse(work.application.draft);validationScope=null;dirty=false;conflict=false;busy=!!work.application.active_request;section=work.application.last_section||'case';const key=`lease:${me.id}:${id}`;
    const check=()=>{const old=JSON.parse(localStorage.getItem(key)||'null');readOnlyTab=!!old&&old.tab!==tab&&Date.now()-old.at<20000;if(!readOnlyTab)localStorage.setItem(key,JSON.stringify({tab,at:Date.now()}));};check();clearInterval(leaseTimer);leaseTimer=setInterval(check,5000);
    const recovery=sessionStorage.getItem(recoveryKey());if(recovery&&work.application.state!=='submitted'&&!readOnlyTab){const r=JSON.parse(recovery);if(r.revision===Number(work.application.revision)&&confirm('Bu hesap ve vaka için sunucuya ulaşmamış taslak bulundu. Kurtarılsın mı?')){work.draft=r.draft;dirty=true;event('recovered');}else if(r.revision!==Number(work.application.revision))notify('Eski kurtarma taslağı korunuyor; sunucu sürümü değiştiği için otomatik uygulanmadı.');}
    events=JSON.parse(sessionStorage.getItem(recoveryKey()+':events')||'[]');seq=Math.max(Number(sessionStorage.getItem(recoveryKey()+':seq')||0),...events.map(e=>e.seq));clearInterval(heartbeatTimer);heartbeatTimer=setInterval(()=>{event('heartbeat');flushEvents();if(busy)refreshChat().catch(()=>{});},me.config.heartbeat_ms);renderWork();event('section_open');if(dirty)scheduleSave();
}
function locked(){return work.application.state==='submitted'||readOnlyTab||conflict;}
function sectionLocked(s){return !work.application.initial_at&&['ai','final','reflection','confirm'].includes(s);}
function status(t,error=false){const e=$('#save-status');if(e){e.textContent=t;e.classList.toggle('error',error);}}
function scheduleSave(){dirty=true;localSave();status('Kaydedilmemiş değişiklik var');updateValidationFeedback();clearTimeout(saveTimer);saveTimer=setTimeout(()=>save().catch(e=>notify(e.message)),me.config.autosave_ms);}
async function save(action='save'){clearTimeout(saveTimer);const task=async()=>{if(!work||(!dirty&&action==='save'))return;demandUi(!conflict,'Sürüm çakışmasını çözmeden kayıt yapılamaz.');const id=work.application.id, snapshot=structuredClone(work.draft);saving=true;updateSubmitGate();status('Kaydediliyor…');try{const a=await api(action,{app_id:id,revision:Number(work.application.revision),draft:snapshot});work.application={...work.application,...a};dirty=JSON.stringify(work.draft)!==JSON.stringify(snapshot);if(!dirty)sessionStorage.removeItem(recoveryKey());else localSave();status(dirty?'Kaydedilmemiş değişiklik var':'Sunucuya kaydedildi');return a;}catch(e){localSave();if(e.status===409){conflict=true;notify('Sürüm çakışması / kilit değişimi. Taslağınız bu sekmede korunuyor; metninizi kopyalayıp yeniden yükleyin.');}status(navigator.onLine?e.message:'Bağlantı yok, sunucuya gönderilemedi',true);throw e;}finally{saving=false;updateValidationFeedback();}};saveChain=saveChain.catch(()=>{}).then(task);return saveChain;}
function demandUi(ok,text){if(!ok)throw new Error(text);}
function bindFields(keys){for(const k of keys){const el=$('#'+k);if(!el)continue;el.oninput=()=>{work.draft[k]=el.tagName==='SELECT'?(el.value===''?null:Number(el.value)):el.value;lastInput=Date.now();event(k==='question'?'question_changed':el.tagName==='SELECT'?'profile_changed':'text_changed',{field:k},true);scheduleSave();};el.onfocus=()=>event('field_focus',{field:k});el.onblur=()=>{if(dirty)save().catch(()=>{});};}}
function renderWork(){const a=work.application,d=work.draft,initialLock=!!a.initial_at||locked();$('#root').innerHTML=`<div class="workspace-top"><div class="toolbar"><div><div class="eyebrow">Vaka çalışma alanı · sürüm ${work.version.version}</div><h1>${esc(a.case_title||'Pedagojik vaka')}</h1></div><div class="row"><span class="pill">${esc(stateName(a.state))}</span><span id="save-status" class="status">${dirty?'Kaydedilmemiş değişiklik var':'Sunucudaki sürüm yüklendi'}</span><button id="back" class="secondary">← Vakalarım</button></div></div><nav class="tabs" aria-label="Çalışma bölümleri">${Object.entries(names).map(([k,v],i)=>`<button data-section="${k}" class="${section===k?'active':''}" aria-current="${section===k?'step':'false'}">${i+1}. ${v}${sectionLocked(k)?' · Kilitli':(initialLock&&['profile','initial'].includes(k))||locked()?' · Salt okunur':''}</button>`).join('')}</nav></div><div class="section">${readOnlyTab?'<p class="warning">Bu vaka başka sekmede açık. Bu sekme salt okunur. Diğer sekmeyi kapattıktan 20 saniye sonra yeniden yükleyin.</p>':''}${conflict?'<p class="warning">Sürüm çakışması: taslağı kopyalayıp sunucu sürümünü yeniden yükleyin.</p>':''}${section==='confirm'?'<div id="validation-summary" class="validation-summary" role="alert" hidden></div>':''}<div class="card" id="section-body"></div>${section==='confirm'?reportLinks():''}</div>`;
    let html='';if(sectionLocked(section))html='<h2>Bu bölüm henüz açık değil</h2><p>Başlangıç değerlendirmenizi kesinleştirdiğinizde AI sohbeti, nihai değerlendirme, yansıtma ve son teslim bölümleri açılacaktır.</p>';
    else if(section==='case')html=`<span class="eyebrow">Vaka metni · sürüm ${work.version.version}</span><h2>Durumu inceleyin</h2><div class="prose" data-source="case">${esc(work.version.body)}</div><p class="prose">${esc(work.version.instructions)}</p>`;
    else if(section==='profile')html=`<span class="eyebrow">Başlangıç profili</span><h2>Bu vakaya ilişkin görüşünüz</h2><p class="muted">Her alan başlangıçta boştur. Profiliniz başlangıç yanıtınızla birlikte kesinleşir.</p><div class="grid">${[['knowledge','Ön bilgi: Bu konu hakkında ne kadar bilginiz var?'],['confidence','Başlangıç güveni: Uygun karar verebileceğinize ne kadar güveniyorsunuz?'],['difficulty','Algılanan zorluk'],['severity','Yanlış kararın sonucunun ciddiyeti']].map(([k,l])=>`<div>${numberField(k,l,d[k],initialLock)}</div>`).join('')}</div>`;
    else if(section==='initial')html=`<span class="eyebrow">AI öncesi muhakeme</span><h2>Başlangıç değerlendirmeniz</h2><p class="muted">Kararınızı etkileyen vaka bilgilerini, kişileri, olası riskleri veya sonuçları belirtiniz.</p>${a.initial_at?'<p class="warning">Başlangıç yanıtınız kesinleştirildi. Bu bölüm yalnızca görüntülenebilir.</p>':''}${field('problem','Bu vakadaki temel problemi nasıl değerlendiriyorsunuz?',d.problem,'textarea',initialLock)}${field('decision','Kararınız nedir?',d.decision,'textarea',initialLock)}${field('reason','Bu kararı neden veriyorsunuz?',d.reason,'textarea',initialLock)}<button class="spaced" id="initial" ${initialLock?'disabled':''}>Başlangıç yanıtımı kesinleştir ve AI sohbetini aç</button>`;
    else if(section==='ai')html=`<div class="toolbar"><div><span class="eyebrow">Vaka ile bağımsız sohbet</span><h2>AI ile etkileşim</h2></div><span class="pill" id="ai-status">${busy?'Yanıt üretiliyor':'Tam yanıt aktarımı'}</span></div><p class="muted">Gerçek kişilere ait tanımlayıcı bilgi paylaşmayın. Yalnız vaka ve bu sohbette gönderdiğiniz mesajlar AI'a iletilir.</p><div class="chat" id="chat">${work.messages.map(m=>`<div class="message ${m.role}" data-source="message:${m.id}"><strong>${m.role==='user'?'Siz':'AI'} · ${esc(m.status)} · #${m.seq}</strong>${esc(m.content)}</div>`).join('')||'<p class="empty">Henüz mesaj yok.</p>'}</div>${field('question','Mesaj taslağı',d.question,'textarea',locked())}<div class="row spaced"><button id="send" ${locked()||busy?'disabled':''}>Mesajı gönder</button><small>Akış ölçümü yok; yanıt tamamlandığında gösterilir. Yanıt sürerken diğer bölümlerde yazabilirsiniz.</small></div>`;
    else if(section==='final')html=`<span class="eyebrow">Nihai muhakeme</span><h2>Son kararınız ve gerekçeniz</h2>${field('final_decision','Nihai kararınız nedir?',d.final_decision,'textarea',locked())}${field('final_reason','Nihai kararınızın gerekçesi nedir?',d.final_reason,'textarea',locked())}${numberField('final_confidence','Nihai kararınıza ne kadar güveniyorsunuz?',d.final_confidence,locked())}`;
    else if(section==='reflection')html=`<span class="eyebrow">Süreç üzerine düşünme</span><h2>Yansıtmanız</h2>${field('reflection',"AI ile etkileşiminiz nihai kararınızı nasıl etkiledi? AI'ın hangi önerisini kabul ettiniz, değiştirdiniz veya reddettiniz? Neden?",d.reflection,'textarea',locked())}`;
    else if(section==='confirm')html=`<div class="toolbar"><div><span class="eyebrow">Çalışmayı tamamla</span><h2>Son teslim</h2><p class="muted">Nihai yanıt ve yansıtma birlikte kilitlenir. Sürecinizi sonrasında görüntüleyebilirsiniz.</p></div><button id="submit" aria-describedby="submit-help" ${!canSubmit()?'disabled':''}>Vakayı tamamla ve tüm yanıtlarımı kesinleştir</button></div><div id="submit-help" class="submit-help" aria-live="polite"></div>${a.submitted_at?`<p>Teslim: ${displayTime(a.submitted_at)}</p>`:''}`;
    if(section==='ai'&&!sectionLocked(section))html+=(work.requests||[]).filter(r=>r.status==='failed').map(r=>`<p class="warning">Başarısız AI isteği ${esc(r.id.slice(0,8))}. Öğrenci mesajı korunuyor. <button class="secondary" data-retry-request="${r.id}" ${locked()||busy?'disabled':''}>Aynı mesajı yeniden dene</button></p>`).join('');
    $('#section-body').innerHTML=html;bindFields(['knowledge','confidence','difficulty','severity','problem','decision','reason','question','final_decision','final_reason','final_confidence','reflection']);
    document.querySelectorAll('[data-section]').forEach(b=>{b.onpointerdown=e=>{if(dirty&&e.button===0)e.preventDefault();};b.onclick=async()=>{const old=section;try{if(dirty)await save();section=b.dataset.section;scrolls[old]=window.scrollY;renderWork();window.scrollTo(0,scrolls[section]||0);event('section_open',{locked:sectionLocked(section)});}catch(e){notify(e.message);}};});
    handler('#back',async()=>{if(dirty)await save();await flushEvents();await home();});handler('#initial',async()=>{if(!validateBeforeConfirm('initial'))return;if(!confirm('Başlangıç yanıtınız ve vaka profili yanıtlarınız bundan sonra değiştirilemeyecek. Devam etmek istiyor musunuz?'))return;if(!validateBeforeConfirm('initial'))return;await save('initial');validationScope=null;section='ai';renderWork();event('section_open');});
    handler('#submit',async()=>{if(!validateBeforeConfirm('submit'))return;if(!canSubmit()){notify('Teslim için kayıt ve AI işlemlerinin tamamlanmasını bekleyin.');return;}if(!confirm('Yeni mesaj ve düzenleme yapılamayacak; tüm süreci görüntüleyebileceksiniz. Teslim edilsin mi?'))return;if(!validateBeforeConfirm('submit')||!canSubmit())return;await save('submit');validationScope=null;renderWork();notify('Vaka teslim edildi.');});handler('#send',sendChat);
    if($('#chat'))$('#chat').onscroll=()=>event('scroll',{},true);document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>download({report_ids:b.dataset.report,format:b.dataset.format}));
    document.querySelectorAll('[data-retry-request]').forEach(b=>b.onclick=async()=>{if(!confirm('Sağlayıcıda önceki isteğin maliyeti oluşmuş olabilir. Yeni deneme yapılsın mı? Öğrenci mesajı çoğaltılmayacak.'))return;busy=true;updateSubmitGate();b.disabled=true;try{const r=work.requests.find(r=>r.id===b.dataset.retryRequest);await api('chat',{app_id:a.id,key:r.client_key,retry_request:r.id});const update=await api('view',undefined,{app_id:a.id});work.requests=update.requests;work.messages=update.messages;busy=false;updateSubmitGate();if(section==='ai')renderWork();else notify('Yeniden deneme tamamlandı.');}catch(e){busy=false;updateSubmitGate();notify(e.message);}});
    updateValidationFeedback();
    const activeTab=document.querySelector('[data-section="'+section+'"]');
    if(activeTab){const nav=activeTab.parentElement;nav.scrollLeft=Math.max(0,activeTab.offsetLeft-nav.offsetLeft-(nav.clientWidth-activeTab.offsetWidth)/2);}
}
const scrolls={};
function reportLinks(){return (work.reports||[]).length?`<div class="card"><h2>Yayımlanan raporlar</h2>${work.reports.map(r=>`<p>Sürüm ${r.version} <button class="secondary" data-report="${r.id}" data-format="docx">Word</button> <button class="secondary" data-report="${r.id}" data-format="pdf">PDF</button></p>`).join('')}</div>`:'';}
async function refreshChat(){const target=work;if(!target)return;const updated=await api('view',undefined,{app_id:target.application.id});if(work!==target)return;target.messages=updated.messages;target.requests=updated.requests;target.application.active_request=updated.application.active_request;const wasBusy=busy;busy=!!updated.application.active_request;updateSubmitGate();if(wasBusy&&!busy){if(section==='ai')renderWork();notify('AI işlemi tamamlandı. Sohbet bölümünden görüntüleyebilirsiniz.');}}
async function sendChat(){if(busy||locked())return;const target=work,text=target.draft.question.trim();if(!text)return;await save();const keyName=recoveryKey()+':request';busy=true;updateSubmitGate();const key=sessionStorage.getItem(keyName)||crypto.randomUUID();sessionStorage.setItem(keyName,key);if($('#send'))$('#send').disabled=true;notify('AI yanıtı hazırlanıyor. Diğer bölümlerde çalışmaya devam edebilirsiniz.');
    try{const r=await api('chat',{app_id:target.application.id,text,key});sessionStorage.removeItem(keyName);if(work!==target){notify('Önceki vakadaki AI işlemi tamamlandı.');return;}await refreshChat();if(!busy&&target.draft.question===text){target.draft.question='';scheduleSave();}if(section==='ai')renderWork();else notify(`AI işlemi: ${r.status}. Sohbet bölümünden görüntüleyebilirsiniz.`);event('response_visible',{request:r.id,status:r.status,quality:'full_response_only',in_ai:section==='ai'});
    }catch(e){notify(e.message+' Ağ belirsizliğinde aynı istek kimliğiyle tekrar deneyin.');if(work===target){busy=false;updateSubmitGate();if($('#send'))$('#send').disabled=false;}}}
function event(type,payload={},throttle=false){if(!work||me?.role!=='student')return;if(throttle&&Date.now()-lastEvent<700)return;if(throttle)lastEvent=Date.now();events.push({key:crypto.randomUUID(),tab,seq:++seq,at:new Date().toISOString(),type,section,payload:{...payload,visible:!document.hidden,focused:document.hasFocus(),interactive:Date.now()-lastInput<me.config.idle_ms}});sessionStorage.setItem(recoveryKey()+':events',JSON.stringify(events));sessionStorage.setItem(recoveryKey()+':seq',String(seq));if(events.length>=20)flushEvents();}
let flushing=false;
async function flushEvents(){if(!work||flushing||!events.length)return;flushing=true;const chunk=events.slice(0,100),id=work.application.id,key=recoveryKey()+':events';try{const r=await api('events',{app_id:id,events:chunk});events=events.filter(e=>!r.accepted.includes(e.key));sessionStorage.setItem(key,JSON.stringify(events));}catch(e){/* keep queue for authenticated retry */}finally{flushing=false;}}
document.addEventListener('visibilitychange',()=>event('visibility'));
window.addEventListener('focus',()=>event('focus'));window.addEventListener('blur',()=>event('focus'));window.addEventListener('offline',()=>{event('offline');status('Bağlantı yok, sunucuya gönderilemedi',true);updateSubmitGate();});window.addEventListener('online',()=>{event('online');flushEvents();updateSubmitGate();if(dirty)save().catch(e=>notify(e.message));});
window.addEventListener('beforeunload',e=>{if(work)event('page_exit');if(dirty){localSave();e.preventDefault();e.returnValue='';}});
document.addEventListener('paste',e=>{if(e.target.matches('textarea,input'))event('paste',{field:e.target.id});});
document.addEventListener('copy',()=>{if(!work)return;const el=document.activeElement;let source=section,quote='',start=null,end=null;if(el?.matches('textarea,input')){start=el.selectionStart;end=el.selectionEnd;quote=el.value.slice(start,end);source=el.id;}else{const s=window.getSelection();quote=s?.toString()||'';const node=s?.anchorNode?.parentElement?.closest('[data-source]');source=node?.dataset.source||section;if(s?.rangeCount){const range=s.getRangeAt(0);if(node&&node.contains(range.startContainer)&&node.contains(range.endContainer)){const pre=range.cloneRange();pre.selectNodeContents(node);pre.setEnd(range.startContainer,range.startOffset);start=pre.toString().length;end=start+quote.length;}}}event('copy',{source,version:work.version.id,revision:work.application.revision,start,end,length:quote.length,quote:quote.slice(0,6000)});});
let adminTab='overview';
async function adminHome(){dash=await api('dashboard');$('#root').innerHTML=`<div class="eyebrow">Araştırmacı paneli</div><h1>Araştırmanın bütününe bir bakış.</h1><p class="intro">Katılımcıları ve vaka süreçlerini izleyin; ham veri, AI önerisi ve araştırmacı kararını ayrı inceleyin.</p><nav class="tabs">${[['overview','Genel durum'],['participants','Katılımcılar'],['cases','Vakalar ve atamalar'],['definitions','Rubrikler ve etiketler'],['exports','Veri indirme'],['system','Sistem ve işlem geçmişi']].map(([k,l])=>`<button data-admin-tab="${k}" class="${adminTab===k?'active':''}">${l}</button>`).join('')}</nav><div id="admin-body" class="spaced"></div>`;document.querySelectorAll('[data-admin-tab]').forEach(b=>b.onclick=()=>{adminTab=b.dataset.adminTab;adminHome().catch(e=>notify(e.message));});renderAdmin();}
const select=(id,label,opts,value='')=>`<label for="${id}">${label}</label><select id="${id}">${opts.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`).join('')}</select>`;
function renderAdmin(){const students=dash.users.filter(u=>u.role==='student'),defs=dash.definitions;let html='';
    if(adminTab==='overview'){const apps=dash.applications;html=`<div class="metrics"><div class="metric"><small>Katılımcı</small><strong>${students.length}</strong></div><div class="metric"><small>Başlamış uygulama</small><strong>${apps.length}</strong></div><div class="metric"><small>Teslim</small><strong>${apps.filter(a=>a.state==='submitted').length}</strong></div><div class="metric"><small>Veri toplama</small><strong>${dash.study.closed_at?'Kapalı':'Açık'}</strong></div></div><div class="card"><div class="toolbar"><h2>Öğrenci × vaka matrisi</h2><input id="matrix-filter" placeholder="Öğrenci numarasıyla filtrele" aria-label="Öğrenci filtresi"></div><p class="muted">Son bölüm ve son etkinlik canlı varlık kanıtı değildir. Hücreyi seçerek dosyayı açın.</p><div class="table-wrap"><table><thead><tr><th>Öğrenci no</th>${dash.cases.map(c=>`<th>${esc(c.title)}<br><small>${esc(c.status)} · v${c.version}</small></th>`).join('')}</tr></thead><tbody>${students.map(u=>`<tr data-student="${esc(u.login)}"><td><strong>${esc(u.login)}</strong><br><small>${esc(u.status)}</small></td>${dash.cases.map(c=>{const a=apps.find(a=>a.user_id===u.id&&a.case_id===c.id),assigned=dash.assignments.find(s=>s.user_id===u.id&&s.case_id===c.id&&Number(s.active));return `<td>${a?`<button class="cell-button" data-process="${a.id}">${a.excluded?'Analiz dışı':stateName(a.state)}${a.active_request?' · AI işlemi':''}</button><br><small>${esc(a.last_section||'—')} · ${displayTime(a.last_activity)}</small>`:assigned?(c.status==='active'?'Açmadı':'Henüz aktif değil'):'Atanmadı'}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div></div>`;}
    if(adminTab==='participants')html=`<div class="toolbar"><h2>Katılımcılar</h2><button id="add-participant">+ Katılımcı ekle</button></div><div class="card table-wrap"><table><thead><tr><th>Öğrenci no</th><th>Ad</th><th>Durum</th><th>İşlem</th></tr></thead><tbody>${students.map(u=>`<tr><td>${esc(u.login)}</td><td>${esc(u.name)}</td><td>${esc(u.status)}</td><td><button class="secondary" data-edit-user="${u.id}">Düzenle / Dondur / Arşivle</button></td></tr>`).join('')}</tbody></table></div>`;
    if(adminTab==='cases')html=`<div class="toolbar"><h2>Vakalar ve atamalar</h2><div class="row"><button id="add-case">+ Vaka ekle</button><button class="secondary" id="assignment">Atama yönet</button></div></div><div class="cards">${dash.cases.map(c=>`<div class="card"><span class="pill">${esc(c.status)} · v${c.version}</span><h2 class="spaced">${esc(c.title)}</h2><p>${c.practice?'Deneme · Araştırma dışı':'Araştırma vakası'}</p><div class="row"><button class="secondary" data-preview="${c.id}">Öğrenci önizlemesi</button><button data-edit-case="${c.id}">Düzenle / Yeni sürüm</button></div></div>`).join('')}</div>`;
    if(adminTab==='definitions')html=`<div class="toolbar"><h2>Rubrikler ve etiketler</h2><div class="row"><button id="add-rubric">+ Rubrik</button><button class="secondary" id="add-label">+ Etiket</button></div></div><p class="warning">Gerçek rubrik henüz sağlanmadı. TEST RUBRİĞİ yalnızca sentetik kontrol içindir. Düzenleme yeni sürüm oluşturur; önceki tanımlar korunur.</p>${defs.map(d=>`<div class="card"><div class="toolbar"><h3>${esc(d.name)} <span class="pill">${esc(d.family)} · v${d.version}${d.archived?' · Kullanımdan kaldırıldı':''}</span></h3><button class="secondary" data-edit-def="${d.id}">Yeni sürüm / Kullanımdan kaldır</button></div><details><summary>Tanım</summary>${pretty(d.body)}</details></div>`).join('')}`;
    if(adminTab==='exports')html=`<div class="card"><h2>Process mining ve veri indirme</h2><p class="muted">Varsayılan çıktı test, deneme ve analiz dışı veriyi dışlar. Kodlanmış çıktı serbest metinleri çıkarır. Mesaj etiketleri ayrı tabloda bulunur.</p><p>Olayları okumak için <b>events</b> sayfasındaki <b>type_tr</b> (Türkçe olay adı), <b>section_tr</b> (bölüm), <b>event_category</b> (olay grubu) ve <b>event_description</b> (açıklama) sütunlarını kullanın. <b>dictionary</b> sayfası tüm kodları açıklar. <b>heartbeat = Periyodik durum kaydı</b>; okuma veya kullanıcı eylemi kanıtı değildir.</p>${select('export-user','Kapsam',[['','Tüm katılımcılar'],...students.map(u=>[u.id,u.login])])}<label class="inline-check"><input id="include-test" type="checkbox">Sentetik test verisini dahil et</label><label class="inline-check"><input id="include-practice" type="checkbox">Deneme vakalarını dahil et</label><label class="inline-check"><input id="include-excluded" type="checkbox">Analiz dışı veriyi dahil et</label><label class="inline-check"><input id="coded" type="checkbox" checked>Kodlanmış çıktı (kimlik/metin yok)</label>${select('csv-table','CSV tablosu',['events','visits','messages','labels','drafts','snapshots','applications','analyses','decisions','dictionary'].map(t=>[t,t]))}<div class="row spaced"><button data-export="xlsx">Excel (.xlsx)</button><button class="secondary" data-export="csv">CSV</button><button class="secondary" data-export="json">Yapısal JSON</button></div></div>`;
    if(adminTab==='system')html=`<div class="card"><h2>Global veri toplama durumu</h2><p>${dash.study.closed_at?'Kapalı · '+displayTime(dash.study.closed_at):'Açık · Öğrenciye puan/rapor yayımlanamaz.'}</p><p class="warning">Kapanış bütün araştırma içindir. Beş vakanın veri toplamasını ve eksik/çekilmiş katılımcıları kontrol edip gerekçeyi belgeleyin. Kapanış raporları otomatik yayımlamaz.</p><button class="danger" id="close-study" ${dash.study.closed_at?'disabled':''}>Araştırma genelinde veri toplamayı kapat</button></div><div class="card"><h2>Sistem bilgisi</h2><p>${me.mock?'SENTETİK MOCK':'Yapılandırılmış sağlayıcı'} · Tam yanıt aktarımı; streaming ölçülmez.</p><p>Autosave ${me.config.autosave_ms} ms · Heartbeat ${me.config.heartbeat_ms} ms · Idle ${me.config.idle_ms} ms · measurement-v1</p><p>Sağlayıcı/model/anahtar ve kurum onamı güvenli sunucu yapılandırmasından yönetilir. Anahtarlar bu panele gönderilmez.</p></div><div class="card"><h2>İşlem geçmişi (son 100)</h2>${pretty(dash.audit)}</div>`;
    $('#admin-body').innerHTML=html;
    if($('#matrix-filter')){const bar=document.createElement('div');bar.className='grid';bar.innerHTML=select('matrix-case','Vaka',[['','Tüm vakalar'],...dash.cases.map(c=>[c.id,c.title])])+select('matrix-version','Vaka sürümü',[['','Tüm sürümler'],...dash.versions.map(v=>[v.id,(dash.cases.find(c=>c.id===v.case_id)?.title||v.case_id)+' · v'+v.version])])+select('matrix-state','Süreç durumu',[['','Tümü'],['unopened','Açmadı'],['initial','Başlangıç'],['working','Devam ediyor'],['submitted','Teslim'],['excluded','Analiz dışı'],['technical','Teknik sorun']])+select('matrix-archive','Hesap görünümü',[['all','Tümü'],['active','Etkin'],['archived','Arşiv']])+select('matrix-analysis','AI analizi',[['','Tümü'],['none','Başlamadı'],['started','Başladı'],['completed','Tamamlandı']])+select('matrix-report','Rapor',[['','Tümü'],['none','Yok'],['draft','İncelemede'],['approved','Onaylı'],['published','Yayımlandı']]);$('#matrix-filter').closest('.toolbar').after(bar);['matrix-filter','matrix-case','matrix-version','matrix-state','matrix-archive','matrix-analysis','matrix-report'].forEach(k=>$('#'+k).addEventListener('input',filterMatrix));}
    document.querySelectorAll('[data-process]').forEach(b=>b.onclick=()=>processView(b.dataset.process).catch(e=>notify(e.message)));
    handler('#add-participant',()=>participantForm());document.querySelectorAll('[data-edit-user]').forEach(b=>b.onclick=()=>participantForm(dash.users.find(u=>u.id===b.dataset.editUser)));
    handler('#add-case',()=>caseForm());document.querySelectorAll('[data-edit-case]').forEach(b=>b.onclick=()=>caseForm(dash.cases.find(c=>c.id===b.dataset.editCase)));
    document.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>{const c=dash.cases.find(c=>c.id===b.dataset.preview);showDialog(`<span class="eyebrow">Öğrenci önizlemesi · v${c.version}</span><h2>${esc(c.title)}</h2><div class="prose">${esc(c.body)}</div><p class="prose">${esc(c.instructions)}</p>`);});
    handler('#assignment',assignmentForm);handler('#add-rubric',()=>definitionForm('rubric'));handler('#add-label',()=>definitionForm('label'));document.querySelectorAll('[data-edit-def]').forEach(b=>b.onclick=()=>{const d=defs.find(d=>d.id===b.dataset.editDef);definitionForm(d.family,d);});
    document.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>download({format:b.dataset.export,table:getValue('csv-table'),user_id:getValue('export-user'),include_test:$('#include-test').checked?1:0,include_practice:$('#include-practice').checked?1:0,include_excluded:$('#include-excluded').checked?1:0,coded:$('#coded').checked?1:0}));
    handler('#close-study',()=>showDialog(`<h2>Global kapanışı kaydet</h2><p>Beş araştırma vakasının veri toplaması kapandı mı? Eksik katılımcılar için gerekçeleri yazın.</p>${field('reason','Kapanış ve eksik/çekilmiş katılımcı gerekçeleri','','textarea')}<button class="danger spaced" id="commit">Kapanışı onayla</button>`,async()=>{await api('admin',{action:'close_study',reason:getValue('reason'),confirm:true});await adminHome();}));
}
function participantForm(u){const m=u?JSON.parse(u.metadata):{};showDialog(`<h2>${u?'Katılımcıyı düzenle':'Katılımcı ekle'}</h2>${field('p-login','Öğrenci numarası',u?.login)}${field('p-name','Ad soyad (testte sentetik)',u?.name)}${field('p-password',u?'Yeni parola (boşsa korunur)':'Parola (en az 12 karakter)','','password')}${select('p-status','Hesap durumu',[['active','Etkin'],['frozen','Dondurulmuş'],['archived','Arşiv']],u?.status||'active')}${field('p-program','Program',m.program)}${field('p-year','Sınıf',m.year)}${field('p-consent','Onam durumu',m.consent)}${field('p-experience','Önceki GenAI deneyimi',m.experience)}${field('p-tools','Kullanılan araçlar',m.tools)}${field('p-withdrawal','Çekilme durumu / talebi',m.withdrawal_request)}${field('p-notes','Araştırmacıya özel katılımcı notu',m.researcher_notes,'textarea')}${field('reason','İşlem gerekçesi','','textarea')}<button class="spaced" id="commit">Kaydet</button>`,async()=>{await api('admin',{action:'participant',...(u?{id:u.id}:{}),login:getValue('p-login'),name:getValue('p-name'),password:getValue('p-password'),status:getValue('p-status'),metadata:{...m,program:getValue('p-program'),year:getValue('p-year'),consent:getValue('p-consent'),experience:getValue('p-experience'),tools:getValue('p-tools'),withdrawal_request:getValue('p-withdrawal'),researcher_notes:getValue('p-notes')},reason:getValue('reason')});await adminHome();});}
function caseForm(c){showDialog(`<h2>${c?'Yeni vaka sürümü':'Vaka oluştur'}</h2>${field('c-title','Başlık',c?.title)}${field('c-position','Sıra',c?.position||1,'number')}${field('c-body','Vaka metni',c?.body,'textarea')}${field('c-instructions','Öğrenci yönergeleri',c?.instructions,'textarea')}${field('c-notes','Araştırmacıya özel notlar',c?.notes,'textarea')}${select('c-status','Durum',[['draft','Taslak'],['active','Aktif'],['closed','Yeni başlangıçlara kapalı'],['archived','Arşiv']],c?.status||'draft')}${select('c-rubric','Rubrik',[['','Henüz bağlı değil'],...dash.definitions.filter(d=>d.family==='rubric'&&!Number(d.archived)&&!dash.definitions.some(n=>n.parent_id===d.id)).map(d=>[d.id,d.name+' · v'+d.version])],c?.rubric_id||'')}<label class="inline-check"><input type="checkbox" id="c-practice" ${Number(c?.practice)?'checked':''}>Deneme vakası</label><label class="inline-check"><input type="checkbox" id="c-stop" ${Number(c?.stop_access)?'checked':''}>Devam eden erişimi de durdur (gerekçeli)</label>${field('reason','İşlem gerekçesi','','textarea')}<button class="spaced" id="commit">Vaka sürümünü kaydet</button>`,async()=>{await api('admin',{action:'case',...(c?{id:c.id}:{}),title:getValue('c-title'),body:getValue('c-body'),instructions:getValue('c-instructions'),notes:getValue('c-notes'),position:Number(getValue('c-position')),status:getValue('c-status'),rubric_id:getValue('c-rubric'),practice:$('#c-practice').checked,stop_access:$('#c-stop').checked,reason:getValue('reason')});await adminHome();});}
function assignmentForm(){showDialog(`<h2>Atama yönetimi</h2>${select('a-user','Öğrenci',dash.users.filter(u=>u.role==='student').map(u=>[u.id,u.login]))}${select('a-case','Vaka',dash.cases.map(c=>[c.id,c.title]))}${select('a-active','Atama durumu',[['1','Ata / Yeniden etkinleştir'],['0','Atamayı kaldır (veri korunur)']])}${field('reason','Gerekçe','','textarea')}<button class="spaced" id="commit">Atamayı kaydet</button>`,async()=>{await api('admin',{action:'assign',user_id:getValue('a-user'),case_id:getValue('a-case'),active:getValue('a-active')==='1',reason:getValue('reason')});await adminHome();});}
const testRubric={text:'TEST RUBRİĞİ — gerçek araştırmada kullanılmaz.',dimensions:[{id:'reasoning',name:'Gerekçelendirme',min:0,max:4,weight:1,levels:[{name:'Yetersiz',score:0,description:'Kanıt yok'},{name:'Gelişiyor',score:2,description:'Kısmi kanıt'},{name:'Ayrıntılı',score:4,description:'Açık gerekçe'}]}]};
function definitionForm(family,d){showDialog(`<h2>${family==='rubric'?'Rubrik':'Etiket'} ${d?'yeni sürümü':'tanımla'}</h2>${field('d-name','Ad',d?.name)}${field('d-body',family==='rubric'?'Yapılandırılmış rubrik JSON (text, dimensions, min/max/weight/levels)':'Açıklama JSON',JSON.stringify(d?JSON.parse(d.body):family==='rubric'?testRubric:{description:''},null,2),'textarea')}<label class="inline-check"><input id="d-archive" type="checkbox">Yeni sürümü kullanımdan kaldırılmış olarak kaydet</label>${field('reason','Gerekçe','','textarea')}<button class="spaced" id="commit">Yeni sürümü kaydet</button>`,async()=>{await api('admin',{action:'definition',family,name:getValue('d-name'),body:JSON.parse(getValue('d-body')),parent_id:d?.id||null,archived:$('#d-archive').checked,reason:getValue('reason')});await adminHome();});}
async function processView(id){const v=await api('view',undefined,{app_id:id}),a=v.application,u=dash.users.find(u=>u.id===a.user_id),c=dash.cases.find(c=>c.id===a.case_id);$('#root').innerHTML=`<div class="toolbar"><div><div class="eyebrow">Öğrenci-vaka dosyası · ${esc(a.id)}</div><h1>${esc(u.login)} · ${esc(c.title)}</h1><span class="pill">${esc(stateName(a.state))}</span></div><button class="secondary" id="admin-back">← Genel durum</button></div><div class="card"><h2>Özet ve veri bütünlüğü</h2><p>Vaka sürümü ${v.version.version} · Başlangıç ${displayTime(a.initial_at)} · Teslim ${displayTime(a.submitted_at)}</p><div class="row"><button class="secondary" id="exclude">${Number(a.excluded)?'Analize dahil et':'Analiz dışı işaretle'}</button><button class="secondary" id="process-json">Ham JSON indir</button></div></div><div class="card"><div class="toolbar"><h2>Ham veriler ve süreç</h2><button class="secondary" id="add-note">İç araştırmacı notu ekle</button></div><p class="muted">JSON içindeki zamanlar, özgün UTC biçimindedir (Z). Üstteki özet ve matris tarihleri yapılandırılmış saat diliminde gösterilir.</p><details><summary>İç not geçmişi (öğrenciye gösterilmez)</summary>${pretty(v.research_notes)}</details><details><summary>1. Görülen vaka</summary><div class="prose">${esc(v.version.body)}</div></details><details><summary>2. Profil, başlangıç, nihai ve yansıtma (taslak / kilit durumu yukarıda)</summary>${pretty(a.draft)}${pretty(v.snapshots)}</details><details><summary>3. AI konuşması ve mesaj etiketleri</summary>${v.messages.map(m=>`<div class="message"><strong>#${m.seq} ${esc(m.role)} · ${esc(m.status)}</strong>${esc(m.content)}${labelCurrent(m.id,v)}<div class="message-tools"><button class="secondary" data-label-message="${m.id}">Etiketleri incele / Değiştir</button></div></div>`).join('')}<details><summary>Ham etiket kayıtları (JSON)</summary>${pretty(v.labels)}</details></details><details><summary>4. Taslak sürümleri</summary>${pretty(v.draft_revisions)}</details><details><summary>5. Olay çizelgesi</summary>${pretty(v.events)}</details><details><summary>6. Süreler ve ölçüm kalitesi</summary>${pretty(v.timing)}<p>AI kulvarı (öğrenci sürelerine eklenmez):</p>${pretty(v.ai_requests.map(r=>({id:r.id,status:r.status,started_at:r.started_at,completed_at:r.completed_at,first_chunk:'ölçülmedi'})))}</details><details><summary>7. AI istekleri / Hata / Girdi sözleşmesi</summary>${v.ai_requests.map(r=>`<h3>${esc(r.status)} · ${r.id}</h3>${pretty(r)}${r.status==='running'?`<button class="danger" data-resolve="${r.id}">Timeout sonrası gerekçeli kapat</button>`:''}`).join('')}</details></div><div class="card"><div class="toolbar"><h2>Ayrı sıralı AI ön değerlendirmesi</h2><button id="new-run" ${a.state!=='submitted'?'disabled':''}>Yeni analiz sürümü</button></div><p class="muted">Tek öğrenci-vaka; başlangıç ve nihai rubrik girdileri bağımsızdır. 1 ve 2 uygulama hesabı; 8 rapor birleştirmedir.</p>${v.analysis_runs.map(run=>renderRun(run,v)).join('')||'<p>Henüz analiz yok.</p>'}</div><div class="card"><h2>Rapor geçmişi · Onay ve yayın</h2>${v.reports.map(r=>`<details><summary>Sürüm ${r.version} · ${r.published_at?'Yayımlandı':r.approved_at?'Onaylı / Yayımlanmadı':'İncelemede'}</summary>${pretty(r.body)}<div class="row">${!r.approved_at?`<button data-report-action="approve" data-id="${r.id}">Raporu onayla</button>`:!r.published_at?`<button data-report-action="publish" data-id="${r.id}">Ayrıca öğrenciye yayımla</button>`:''}<button class="secondary" data-report="${r.id}" data-format="docx">Word</button><button class="secondary" data-report="${r.id}" data-format="pdf">PDF</button></div></details>`).join('')||'<p>Henüz rapor yok.</p>'}${v.reports.length?'<button id="combined" class="secondary">Bu öğrencinin raporlarını birleştir (Word)</button>':''}</div>`;
    handler('#add-note',()=>showDialog(`<h2>İç araştırmacı notu</h2>${field('note-body','Not','','textarea')}${field('reason','Gerekçe','','textarea')}<button id="commit" class="spaced">Notu ekle</button>`,async()=>{await api('admin',{action:'note',app_id:id,body:getValue('note-body'),reason:getValue('reason')});await processView(id);}));handler('#admin-back',()=>adminHome());handler('#process-json',()=>download({format:'json',app_id:id,include_test:1,include_practice:1,include_excluded:1,coded:0}));handler('#exclude',()=>showDialog(`<h2>Analiz kapsamını değiştir</h2>${field('reason','Gerekçe','','textarea')}<button id="commit" class="spaced">Kaydet</button>`,async()=>{await api('admin',{action:'exclude',id,excluded:!Number(a.excluded),reason:getValue('reason')});await processView(id);}));
    handler('#new-run',()=>showDialog(`<h2>Tek vaka için yeni analiz</h2>${select('run-rubric','Rubrik sürümü',dash.definitions.filter(d=>d.family==='rubric'&&!Number(d.archived)&&!dash.definitions.some(n=>n.parent_id===d.id)).map(d=>[d.id,d.name+' v'+d.version]))}<button id="commit" class="spaced">Analizi oluştur</button>`,async()=>{await api('new_run',{app_id:id,rubric_id:getValue('run-rubric')});await processView(id);}));
    document.querySelectorAll('[data-next-step]').forEach(b=>b.onclick=async()=>{if(b.disabled)return;const runEl=b.closest('[data-analysis-run]');runEl.querySelectorAll('[data-next-step]').forEach(el=>el.disabled=true);b.textContent='Çalışıyor…';runEl.querySelector(`[data-analysis-step="${b.dataset.nextStep}"] [data-step-status]`).textContent='Çalışıyor';try{const s=await api('step',{run_id:b.dataset.run,step:Number(b.dataset.nextStep)});notify(s.status==='failed'?'Adım başarısız; çıktı puana çevrilmedi.':'Adım tamamlandı.');await processView(id);}catch(e){notify(e.message);await processView(id);}});
    document.querySelectorAll('[data-decide]').forEach(b=>b.onclick=()=>decisionForm(v.steps.find(s=>s.id===b.dataset.decide),id));
    document.querySelectorAll('[data-create-report]').forEach(b=>b.onclick=async()=>{try{await api('report',{action:'create',run_id:b.dataset.createReport});await processView(id);}catch(e){notify(e.message);}});
    document.querySelectorAll('[data-report-action]').forEach(b=>b.onclick=async()=>{try{await api('report',{action:b.dataset.reportAction,id:b.dataset.id});await processView(id);}catch(e){notify(e.message);}});
    document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>download({report_ids:b.dataset.report,format:b.dataset.format}));
    handler('#combined',async()=>{const ids=[];for(const other of dash.applications.filter(x=>x.user_id===a.user_id)){const ov=await api('view',undefined,{app_id:other.id});ids.push(...ov.reports.map(r=>r.id));}download({report_ids:ids.join(','),format:'docx'});});
    document.querySelectorAll('[data-label-message]').forEach(b=>b.onclick=()=>labelForm(b.dataset.labelMessage,v,id));
    document.querySelectorAll('[data-resolve-analysis]').forEach(b=>b.onclick=()=>showDialog(`<h2>Takılı analiz adımı</h2>${field('reason','Gerekçe','','textarea')}<button id="commit" class="danger spaced">Timeout sonrası kapat</button>`,async()=>{await api('admin',{action:'resolve_analysis',id:b.dataset.resolveAnalysis,reason:getValue('reason')});await processView(id);}));document.querySelectorAll('[data-resolve]').forEach(b=>b.onclick=()=>showDialog(`<h2>Takılı isteği gerekçeli kapat</h2><p>Timeout + 60 saniye dolmalı. Sağlayıcı isteği ayrıca durdurulmuş sayılmaz; geç yanıt attempt kimliğiyle reddedilir.</p>${field('reason','Gerekçe','','textarea')}<button id="commit" class="danger spaced">İsteği başarısız kapat</button>`,async()=>{await api('admin',{action:'resolve_request',id:b.dataset.resolve,reason:getValue('reason')});await processView(id);}));
}
function filterMatrix(){const query=getValue('matrix-filter').toLowerCase(),caseId=getValue('matrix-case'),versionId=getValue('matrix-version'),state=getValue('matrix-state'),account=getValue('matrix-archive'),analysisFilter=getValue('matrix-analysis'),reportFilter=getValue('matrix-report');document.querySelectorAll('[data-student]').forEach(row=>{const u=dash.users.find(u=>u.login===row.dataset.student),cases=caseId?dash.cases.filter(c=>c.id===caseId):dash.cases;const found=cases.some(c=>{const a=dash.applications.find(a=>a.user_id===u.id&&a.case_id===c.id);const as=a?dash.analysis_status.find(x=>x.app_id===a.id):null,rs=a?dash.report_status.find(x=>x.app_id===a.id):null;const analysisState=!as?'none':Number(as.completed_step)===8?'completed':'started',reportState=!rs?'none':rs.published_at?'published':rs.approved_at?'approved':'draft';return (!versionId||a?.version_id===versionId)&&(!state||(state==='unopened'?!a:state==='excluded'?Number(a?.excluded):state==='technical'?dash.technical.some(t=>t.app_id===a?.id):a?.state===state))&&(!analysisFilter||analysisState===analysisFilter)&&(!reportFilter||reportState===reportFilter);});row.hidden=!u.login.toLowerCase().includes(query)||(account!=='all'&&u.status!==account)||!found;});if(caseId){const index=dash.cases.findIndex(c=>c.id===caseId)+1;document.querySelectorAll('.table-wrap tr').forEach(tr=>[...tr.children].forEach((cell,i)=>cell.hidden=i!==0&&i!==index));}else document.querySelectorAll('.table-wrap td,.table-wrap th').forEach(cell=>cell.hidden=false);}
const stepNames={1:'Veri bütünlüğü',2:'Profil ve güven farkı',3:'Başlangıç rubriği',4:'Nihai rubriği',5:'Dönüşüm',6:'Etkileşim ve etiketler',7:'Yansıtma',8:'Rapor birleştirme'};
function renderRun(run,v){
    const progress=analysisProgress(run.id,v),count=progress.filter(p=>p.done).length;
    const statuses={completed:'Tamamlandı',running:'Çalışıyor',ready:'Sıradaki adım',locked:'Kilitli'};
    return `<section class="analysis-run" data-analysis-run="${run.id}"><h3>Analiz ${run.id.slice(0,8)} · ${count}/8 adım</h3><p class="muted">Adımları sırayla çalıştırın. Tamamlanan adımların sonuçlarını açıp inceleyebilirsiniz.</p><ol class="analysis-steps">${progress.map(p=>{
        const {n,status,attempts,done,latest}=p;
        const decision=done?v.decisions.filter(d=>d.step_id===done.id).at(-1):null;
        const reason=status!=='locked'?'':n===8&&progress[6].done?`Önce araştırmacı kararlarını kaydedin: ${p.missingDecisions.join(', ')}. adımlar.`:progress.some(x=>x.status==='running')?'Çalışan adımın tamamlanması bekleniyor.':`Önce ${n-1}. adımı tamamlayın.`;
        return `<li class="analysis-step ${status}" data-analysis-step="${n}"><div class="toolbar"><h3>${n}. ${stepNames[n]}</h3><span class="pill" data-step-status>${statuses[status]}</span></div>${done&&n>=3&&n<=7?`<p class="analysis-review-status">Araştırmacı kararı: ${decision?esc({accept:'Kabul edildi',edit:'Düzenlendi',reject:'Reddedildi',uncertain:'Karar verilemedi'}[decision.action]):'Bekliyor'}</p>`:''}<button data-run="${run.id}" data-next-step="${n}" ${status!=='ready'?'disabled':''}>${status==='completed'?'Tamamlandı':status==='running'?'Çalışıyor…':latest?.status==='failed'?'Yeniden dene':'Adımı çalıştır'}</button>${reason?`<p class="muted">${esc(reason)}</p>`:''}${attempts.length?`<details class="analysis-results"><summary>Sonuçlar ve inceleme (${attempts.length} deneme)</summary>${attempts.map(s=>`<div class="analysis-attempt"><h4>Deneme ${s.attempt} · ${esc({completed:'Tamamlandı',running:'Çalışıyor',failed:'Başarısız'}[s.status]||s.status)}</h4><h3>AI önerisi / uygulama hesabı</h3>${pretty(s.output)}${s.error?`<p class="status error">${esc(s.error)}</p>`:''}${s.status==='running'?`<button class="danger" data-resolve-analysis="${s.id}">Timeout sonrası analiz adımını kapat</button>`:''}<details><summary>Girdi snapshotı</summary>${pretty(s.input)}</details>${s.status==='completed'&&n>=3&&n<=7?`<button class="secondary" data-decide="${s.id}">Kabul / Düzenle / Reddet / Karar verilemedi</button>`:''}${pretty(v.decisions.filter(d=>d.step_id===s.id))}</div>`).join('')}</details>`:''}</li>`;
    }).join('')}</ol>${count===8?`<button data-create-report="${run.id}">Yeni rapor snapshotı oluştur</button>`:''}</section>`;
}
function decisionForm(s,id){showDialog(`<h2>Araştırmacı kararı · ${stepNames[s.step]}</h2>${select('decision-action','Karar',[['accept','Kabul et'],['edit','Düzenle'],['reject','Reddet'],['uncertain','Karar verilemedi']])}${field('decision-body','Düzenleme için onaylı JSON (kabulde AI önerisi kullanılır)',JSON.stringify(JSON.parse(s.output),null,2),'textarea')}${field('reason','Karar gerekçesi','','textarea')}<button id="commit" class="spaced">Kararı ayrı kaydet</button>`,async()=>{await api('decision',{step_id:s.id,action:getValue('decision-action'),body:JSON.parse(getValue('decision-body')),reason:getValue('reason')});await processView(id);});}
function labelNames(ids){return ids.length?ids.map(id=>{const d=dash.definitions.find(d=>d.id===id);return d?`${d.name} · v${d.version}`:`Tanımı bulunamayan etiket (${id})`;}).join(', '):'Etiket yok';}
function labelCurrent(mid,v){const state=labelReviewState(v,mid);return `<p class="label-current"><b>Güncel araştırmacı seçimi:</b> ${esc(state.history.length?labelNames(state.current):'Henüz karar verilmedi')}</p>${state.ai.length?`<p class="muted"><b>AI önerisi (araştırmacı seçimi değildir):</b> ${esc(labelNames(state.ai))}</p>`:''}`;}
function labelForm(mid,v,id){
    const state=labelReviewState(v,mid),message=v.messages.find(m=>m.id===mid);
    const labels=dash.definitions.filter(d=>d.family==='label'&&(!Number(d.archived)&&!dash.definitions.some(n=>n.parent_id===d.id)||state.current.includes(d.id)));
    showDialog(`<h2>Mesaj etiketlerini düzenle</h2><p><b>#${message.seq} · ${message.role==='user'?'Öğrenci':'AI'} mesajı</b></p><blockquote class="label-context">${esc(message.content)}</blockquote>${labelCurrent(mid,v)}<fieldset class="label-options"><legend>Yeni seçim</legend><p class="muted">Güncel etiketler işaretlidir. Eklemek için işaretleyin, kaldırmak için işareti kaldırın. Hiçbiri seçili değilse etiketler temizlenir.</p>${labels.map(l=>`<label class="inline-check"><input type="checkbox" data-choose-label="${esc(l.id)}" ${state.current.includes(l.id)?'checked':''}>${esc(l.name)} · v${l.version}</label>`).join('')}</fieldset><div id="label-change-preview" class="label-change" aria-live="polite"></div>${field('reason','Değişiklik gerekçesi (zorunlu)','','textarea')}<p class="muted">Kaydetmek için seçiminizi açıklayan kısa bir gerekçe yazın.</p><button id="commit" class="spaced">Etiket değişikliğini kaydet</button><details class="label-history"><summary>Değişiklik geçmişi (${state.history.length} karar)</summary>${state.history.length?[...state.history].reverse().map((r,i)=>`<article class="label-review"><h3>Karar ${state.history.length-i}${i===0?' · Güncel':''}</h3><p>${displayTime(r.created_at)} · ${esc(dash.users.find(u=>u.id===r.actor)?.login||r.actor)}</p><p><b>Önceki seçim:</b> ${esc(labelNames(r.before))}</p><p><b>Yeni seçim:</b> ${esc(labelNames(r.ids))}</p><p><b>Eklenenler:</b> ${esc(labelNames(r.added))}</p><p><b>Kaldırılanlar:</b> ${esc(labelNames(r.removed))}</p><p><b>Gerekçe:</b> ${esc(r.reason)}</p></article>`).join(''):'<p>Henüz araştırmacı kararı kaydedilmedi.</p>'}</details><details><summary>Ham etiket kayıtları (JSON)</summary>${pretty({reviews:(v.label_reviews||[]).filter(r=>r.message_id===mid),labels:v.labels.filter(l=>l.message_id===mid)})}</details>`,async()=>{const ids=[...document.querySelectorAll('[data-choose-label]:checked')].map(e=>e.dataset.chooseLabel);await api('admin',{action:'labels',message_id:mid,labels:ids,reason:getValue('reason')});await processView(id);notify('Etiketler kaydedildi. Güncel seçim: '+labelNames(ids));});
    const preview=()=>{const ids=[...document.querySelectorAll('[data-choose-label]:checked')].map(e=>e.dataset.chooseLabel),added=ids.filter(x=>!state.current.includes(x)),removed=state.current.filter(x=>!ids.includes(x));$('#label-change-preview').innerHTML=`<h3>Kaydedilecek değişiklik</h3><p><b>Önce:</b> ${esc(labelNames(state.current))}</p><p><b>Sonra:</b> ${esc(labelNames(ids))}</p><p><b>Eklenenler:</b> ${esc(labelNames(added))}</p><p><b>Kaldırılanlar:</b> ${esc(labelNames(removed))}</p>${!added.length&&!removed.length?'<p>Seçim değişmedi.</p>':''}`;};
    document.querySelectorAll('[data-choose-label]').forEach(el=>el.addEventListener('change',preview));preview();
}
init().catch(e=>notify(e.message));
